    CONSTRAINT "CHK_git_connection_connectionType" CHECK ((("connectionType")::text = ANY ((ARRAY['ssh'::character varying, 'https'::character varying])::text[]))),
    CONSTRAINT "CHK_git_connection_https_auth" CHECK (((("connectionType")::text <> 'https'::text) OR (("publicKey" IS NULL) AND ("encryptedPrivateKey" IS NULL) AND ("keyGeneratorType" IS NULL)))),
    CONSTRAINT "CHK_git_connection_keyGeneratorType" CHECK ((("keyGeneratorType")::text = ANY ((ARRAY['ed25519'::character varying, 'rsa'::character varying])::text[]))),
    CONSTRAINT "CHK_git_connection_ssh_auth" CHECK (((("connectionType")::text <> 'ssh'::text) OR (("encryptedUsername" IS NULL) AND ("encryptedPassword" IS NULL))))
);


